        <a className="big-button x-button" href={xHref} target="_blank" rel="noopener noreferrer"
           onClick={() => countEvent('share_x')}>
          Share on X
        </a>
      </div>
      {error && <p className="inline-error">{error}</p>}
    </section>
  )
}
