import { useCallback, useEffect, useRef, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { api, ApiError, type Audit, type Stats } from '../api'
import DeepCheck from '../components/DeepCheck'
import History from '../components/History'
import RemovalLink from '../components/RemovalLink'
import Result from '../components/Result'
import RoastCard from '../components/RoastCard'
import StepLog from '../components/StepLog'

const POLL_MS = 1500
const ACTIVE_DEEP = ['queued', 'running', 'waiting_budget']

function isActive(a: Audit | null): boolean {
  if (!a) return true
  return a.status === 'queued' || ACTIVE_DEEP.includes(a.phases.deep)
}

export default function AuditPage() {
  const { id = '' } = useParams()
  const [audit, setAudit] = useState<Audit | null>(null)
  const [stats, setStats] = useState<Stats | null>(null)
  const [notFound, setNotFound] = useState(false)
  const [removed, setRemoved] = useState(false)
  const [offline, setOffline] = useState(false)
  const [tick, setTick] = useState(0)
  const timer = useRef<number | undefined>(undefined)

  const poll = useCallback(async () => {
    try {
      const a = await api.getAudit(id)
      setAudit(a)
      setOffline(false)
      return a
    } catch (e) {
      if (e instanceof ApiError && e.status === 404) setNotFound(true)
      else if (e instanceof ApiError && e.status === 410) setRemoved(true)
      else setOffline(true)
      return null
    }
  }, [id])

  // Poll every 1.5s while anything is still running (quick phase or a requested deep check).
  useEffect(() => {
    let alive = true
    const loop = async () => {
      const a = await poll()
      if (!alive) return
      if (isActive(a) && !notFound && !removed) timer.current = window.setTimeout(loop, POLL_MS)
    }
    loop()
    return () => {
      alive = false
      window.clearTimeout(timer.current)
    }
  }, [poll, tick, notFound, removed])

  // Results pages stay out of search engines (Caddy also sends X-Robots-Tag for /a/*).
  useEffect(() => {
    const meta = document.createElement('meta')
    meta.name = 'robots'
    meta.content = 'noindex, nofollow'
    document.head.appendChild(meta)
    return () => meta.remove()
  }, [])

  useEffect(() => {
    api.stats().then(setStats).catch(() => {})
  }, [tick])

  if (removed)
    return (
      <main className="page narrow" data-testid="audit-removed">
        <h1 className="headline">This audit was removed.</h1>
        <p className="lede">
          It's hidden from public view at the owner's request. <Link to="/">Audit a repo</Link>.
        </p>
      </main>
    )

  if (notFound)
    return (
      <main className="page narrow">
        <h1 className="headline">No such audit.</h1>
        <p className="lede">
          That link doesn't match any roast. <Link to="/">Audit a repo</Link>.
        </p>
      </main>
    )

  const report = audit?.result
  const live = !audit || audit.status === 'queued'
  return (
    <main className="page">
      <nav className="topbar">
        <Link to="/" className="brand">🔥 PreJudge</Link>
        {audit && <span className="muted small topbar-repo">{audit.repo_url.replace(/^https?:\/\/(www\.)?github\.com\//, '')}</span>}
      </nav>

      {offline && (
        <p className="notice notice-bad" role="alert" data-testid="offline">
          Lost connection to PreJudge. Retrying…{' '}
          <button className="link-button" onClick={() => setTick((t) => t + 1)}>Retry now</button>
        </p>
      )}

      {audit?.status === 'failed' && (
        <section className="panel error-panel" data-testid="audit-failed">
          <h1 className="headline">The judge tripped.</h1>
          <p className="lede">Something went wrong on our side ({audit.error ?? 'unknown error'}). Your repo is fine.</p>
          <Link className="big-button" to="/">Try again</Link>
        </section>
      )}

      {audit?.queue?.lane === 'quick' && audit.status === 'queued' && audit.queue.position > 1 && (
        <p className="notice notice-warn">In line: {audit.queue.position - 1} audit(s) ahead of you.</p>
      )}

      {report && audit && audit.status !== 'failed' && (
        <>
          <History audit={audit} />
          <Result audit={audit} />
          {!report.score.gated && <DeepCheck audit={audit} stats={stats} onQueued={() => setTick((t) => t + 1)} />}
          {!report.score.gated && (
            <RoastCard
              auditId={audit.id}
              repo={report.repo?.full_name ?? audit.repo_url}
              score={report.score.score}
              roast={report.verdict.roast}
              template={report.verdict.source === 'template'}
              delta={report.progress?.delta}
            />
          )}
        </>
      )}

      {audit && <StepLog steps={audit.steps} live={live || ACTIVE_DEEP.includes(audit.phases.deep)} />}
      {audit && <RemovalLink auditId={audit.id} onRemoved={() => setRemoved(true)} />}
      {!audit && !offline && <StepLog steps={[]} live />}
    </main>
  )
}
import type { Step } from '../api'
import { numberedLabels } from '../labels'

const ICON: Record<Step['status'], string> = { ok: '✓', failed: '✗', skipped: '–' }

export default function StepLog({ steps, live }: { steps: Step[]; live: boolean }) {
  const labels = numberedLabels(steps.map((s) => s.name))
  return (
    <section className="panel steplog" aria-live="polite">
      <h2 className="panel-title">{live ? 'Judging in progress' : 'What the judge did'}</h2>
      <ol>
        {steps.map((s, i) => (
          <li key={i} className={`step step-${s.status}`}>
            <span className="step-icon" aria-hidden>{ICON[s.status]}</span>
            <span className="step-label">{labels[i]}</span>
            {s.status !== 'ok' && s.detail && <span className="step-detail">{s.detail.slice(0, 140)}</span>}
            {s.duration_ms > 400 && <span className="step-time">{(s.duration_ms / 1000).toFixed(1)}s</span>}
          </li>
        ))}
        {live && (
          <li className="step step-running">
            <span className="spinner" aria-hidden />
            <span className="step-label">Working…</span>
          </li>
        )}
      </ol>
    </section>
  )
}
import { formatWait } from '../labels'

export default function BudgetBanner({ state, waitS }: { state: 'normal' | 'busy' | 'cooling'; waitS: number }) {
  if (state === 'normal') return null
  if (state === 'cooling')
    return (
      <p className="notice notice-cool" data-testid="budget-banner">
        The roast oven is cooling (our AI budget for today is used up). You'll get quick facts now and the full
        roast later.
      </p>
    )
  return (
    <p className="notice notice-warn" data-testid="budget-banner">
      Busy right now: deep checks are queued ({formatWait(waitS)}). Quick results are still instant.
    </p>
  )
}
import { useState } from 'react'
import { api, ApiError, type Audit, type Stats } from '../api'
import { formatWait } from '../labels'

// "Run deep check": queue the claim verification, then show position and ETA until it's done.
export default function DeepCheck({ audit, stats, onQueued }: { audit: Audit; stats: Stats | null; onQueued: () => void }) {
  const [error, setError] = useState<string | null>(null)
  const [sending, setSending] = useState(false)
  const deep = audit.phases.deep

  if (audit.status === 'complete') return null
  if (deep === 'skipped') return null

  if (['queued', 'running', 'waiting_budget'].includes(deep)) {
    const q = audit.queue
    let msg = 'Deep check queued…'
    if (deep === 'running') msg = 'Deep check running: reading the code and judging every claim…'
    else if (deep === 'waiting_budget' || q?.waiting_for_budget)
      msg = "Waiting for the judge models' daily budget. Your spot is saved; this page updates itself."
    else if (q) msg = `Deep check queued: position ${q.position}, ${formatWait(q.estimated_wait_s)}`
    return (
      <section className="panel deep-panel" data-testid="deep-status">
        <span className="spinner" aria-hidden /> <span>{msg}</span>
      </section>
    )
  }

  const run = async () => {
    setSending(true)
    setError(null)
    try {
      await api.requestDeep(audit.id)
      onQueued()
    } catch (e) {
      setError(e instanceof ApiError && e.network ? "Can't reach PreJudge. Try again?" : (e as Error).message)
    } finally {
      setSending(false)
    }
  }

  return (
    <section className="panel deep-panel">
      <div>
        <h2 className="panel-title">Want the full trial?</h2>
